<script setup lang="ts">import{ref}from'vue';import AppHeader from'../../components/AppHeader.vue';import StatusNotice from'../../components/StatusNotice.vue';import{api}from'../../api/client';const input=ref(''),supportRef=ref(''),loading=ref(false),error=ref('');async function submit(){loading.value=true;error.value='';try{supportRef.value=(await api.recoverOrder(input.value)).supportRef}catch{error.value='暂时无法提交，请保留当前信息后稍后重试。'}finally{loading.value=false}}</script>
<template><view class="page"><AppHeader left="返回" @left="uni.navigateBack()"/><view class="content"><view class="heading" role="heading" aria-level="1">找回订单</view><text class="desc">填写下单时使用的信息，我们会帮助你查找订单。</text><view class="field"><text class="label">下单信息</text><input v-model="input" placeholder="请输入下单时使用的号码或信息"/></view><StatusNotice v-if="error" tone="risk" title="暂时无法提交">{{error}}</StatusNotice><StatusNotice v-if="supportRef" title="请求已收到">我们会继续查找，你也可以联系在线帮助。</StatusNotice></view><view class="action"><button class="primary" :disabled="loading||!input" @click="submit">{{loading?'正在提交…':'提交查找请求'}}</button><button class="secondary" @click="uni.navigateTo({url:'/pages/support/case'})">联系帮助</button></view></view></template><style src="../../styles/shared.css"></style><style scoped>.field{margin-top:28rpx;background:#fff;border:1rpx solid var(--line);padding:24rpx;border-radius:22rpx}.label{display:block;color:var(--muted);font-size:22rpx;margin-bottom:14rpx}</style>
